script:
// stock_addon: patches the standard General Ledger report:
//  1. Suppresses Frappe's broken auto-footer total (it summed the Balance
//     column, which is a running balance — summing those is meaningless).
//  2. Injects a Customer / Party Name column (resolved from party or the
//     'against' customer code) immediately before Debit.
//  3. Renames the Balance column to 'Running Balance' for clarity.
//  4. Adds a Print PDF button matching the other Stock Addon reports.

frappe.ready(function () {
	function waitForReport(cb) {
		const t = setInterval(function () {
			if (window.cur_report && cur_report.data !== undefined) {
				clearInterval(t);
				cb(cur_report);
			}
		}, 300);
	}

	waitForReport(function (report_obj) {
		// ── Suppress Frappe's broken auto-footer ────────────────────────────
		// The standard GL report.json sets add_total_row=1, which makes the
		// framework append a footer that sums *every* numeric column —
		// including the running Balance, producing a nonsense number.
		// The Python GL already emits an accurate per-period Total and
		// Closing-balance row, so we don't need the auto-footer at all.
		if (report_obj.report_doc) report_obj.report_doc.add_total_row = 0;
		report_obj.add_total_row = 0;

		// ── Print PDF button ────────────────────────────────────────────────
		if (report_obj.page && !report_obj._sa_print_added) {
			report_obj._sa_print_added = true;
			report_obj.page.add_inner_button(__("Print PDF"), function () {
				const data = report_obj.data || [];
				if (!data.length) { frappe.msgprint(__("Run the report first.")); return; }
				frappe.call({
					method: "stock_addon.stock_addon.report.general_ledger_running_balance.general_ledger_running_balance.get_pdf_html",
					args: {
						filters: JSON.stringify(report_obj.get_values()),
						data: JSON.stringify(data),
						columns: JSON.stringify((report_obj.columns || []).map(function (c) {
							return (typeof c === "object") ? c : { fieldname: c, label: c };
						}))
					},
					freeze: true,
					freeze_message: __("Generating PDF..."),
					callback: function (r) {
						if (r.message) {
							var w = window.open();
							w.document.write(r.message);
							w.document.close();
							setTimeout(function () { w.print(); }, 600);
						}
					}
				});
			}).addClass("btn-primary");
		}

		// ── Patch after_render: inject party name + relabel balance ─────────
		if (!report_obj._sa_patched) {
			report_obj._sa_patched = true;
			var _origRender = report_obj.after_render;
			report_obj.after_render = function () {
				if (typeof _origRender === "function") _origRender.apply(this, arguments);
				_processReport(report_obj);
			};
			_processReport(report_obj); // also run once on initial load
		}
	});

	function _processReport(report_obj) {
		var cols = report_obj.columns || [];

		// Inject party name column immediately before debit (idempotent)
		var hasCol = cols.some(function (c) {
			return (typeof c === "object" ? c.fieldname : c) === "party_name";
		});
		if (!hasCol) {
			var debitIdx = cols.findIndex(function (c) {
				return (typeof c === "object" ? c.fieldname : c) === "debit";
			});
			var newCol = {
				label: __("Customer / Party Name"),
				fieldname: "party_name",
				fieldtype: "Data",
				width: 200
			};
			if (debitIdx === -1) cols.push(newCol);
			else cols.splice(debitIdx, 0, newCol);
		}

		// Relabel Balance → Running Balance
		cols.forEach(function (c) {
			if (typeof c === "object" && c.fieldname === "balance") {
				c.label = __("Running Balance");
			}
		});

		// Resolve party names asynchronously, then re-render once.
		var partyCache = {};
		var againstCache = {};
		var nameField = {
			Customer: "customer_name",
			Supplier: "supplier_name",
			Employee: "employee_name"
		};

		var promises = (report_obj.data || []).map(function (row) {
			if (!row || typeof row !== "object") return Promise.resolve();
			if (row.party_name !== undefined && row.party_name !== "") {
				return Promise.resolve();
			}
			if (row.party_type && row.party) {
				var key = row.party_type + "|" + row.party;
				if (partyCache[key] !== undefined) {
					row.party_name = partyCache[key];
					return Promise.resolve();
				}
				var f = nameField[row.party_type];
				if (!f) { row.party_name = ""; return Promise.resolve(); }
				return frappe.db.get_value(row.party_type, row.party, f)
					.then(function (r) {
						var v = (r && r.message && r.message[f]) ? r.message[f] : (row.party || "");
						partyCache[key] = v;
						row.party_name = v;
					})
					.catch(function () { row.party_name = row.party || ""; });
			} else if (row.against) {
				var first = (row.against.split(",")[0] || "").trim();
				if (!first) { row.party_name = ""; return Promise.resolve(); }
				if (againstCache[first] !== undefined) {
					row.party_name = againstCache[first];
					return Promise.resolve();
				}
				return frappe.db.get_value("Customer", first, "customer_name")
					.then(function (r) {
						var v = (r && r.message && r.message.customer_name) ? r.message.customer_name : "";
						againstCache[first] = v;
						row.party_name = v;
					})
					.catch(function () { row.party_name = ""; });
			} else {
				row.party_name = "";
				return Promise.resolve();
			}
		});

		Promise.all(promises).then(function () {
			if (report_obj.render_datatable) {
				report_obj.render_datatable();
			} else if (report_obj.render_report) {
				report_obj.render_report();
			}
		});
	}
});
